<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesUidVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesRoleVO;
use Civi\Lughauth\Features\Access\Role\Domain\RoleRef;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesVersionVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesListRef;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesItem;
use PHPUnit\Framework\TestCase;

class PlatformIdentityRolesListRefUnitTest extends TestCase
{
    public function test_iterator(): void
    {
        $one = new PlatformIdentityRolesItem(
            uid: PlatformIdentityRolesUidVO::from('one'),
            role: PlatformIdentityRolesRoleVO::from(new RoleRef('one')),
            version: PlatformIdentityRolesVersionVO::from(1)
        );
        $two = new PlatformIdentityRolesItem(
            uid: PlatformIdentityRolesUidVO::from('one'),
            role: PlatformIdentityRolesRoleVO::from(new RoleRef('one')),
            version: PlatformIdentityRolesVersionVO::from(1)
        );
        $list = PlatformIdentityRolesListRef::fromArray([$one, $two]);
        foreach ($list as $_K => $item) {
            $this->assertEquals('one', $item->uid());
        }
    }
    public function test_invalid_builder(): void
    {
        $this->expectException(\InvalidArgumentException::class);
        $list = PlatformIdentityRolesListRef::fromArray(['none']);
    }
}
